import json

def format_label(name):
    label = str(name).strip()
    return label

def label(name):
    return format_label(name)

def reject_invalid(value):
    if not isinstance(value, str):
        raise ValueError("name must be text")
    return value.strip()

def dispatch(kind, value):
    with open("handlers.json") as source:
        handler = json.load(source)[kind]
    return globals()[handler](value)

